269	
270	    /**
271	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
272	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
273	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
274	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
275	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
276	     * sequence number, so its base form is a stable function of the owner's region and
277	     * telephone/last-name identity rather than of creation order.
278	     *
279	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
280	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
281	     * existing owner already has; the de-duplicated code is returned.
282	     *
283	     * @param owner the owner being created, with its telephone already normalized to E.164 form
284	     * @return the assigned, collision-free customer code
285	     */
286	    private String customerCodeFor(Owner owner) {
287	        String region = ownerMapper.regionOf(owner);
288	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
289	        String baseCode = region + "-" + hash8;
290	        if (!isCustomerCodeInUse(baseCode)) {
291	            return baseCode;
292	        }
293	        int n = 2;
294	        String candidate = baseCode + "-" + n;
295	        while (isCustomerCodeInUse(candidate)) {
296	            n++;
297	            candidate = baseCode + "-" + n;
298	        }
299	        return candidate;
300	    }
301	
302	    /**
303	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
304	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
305	     *
306	     * @param customerCode the candidate customer code to look for
307	     * @return {@code true} if an existing owner already has that customer code
308	     */
309	    private boolean isCustomerCodeInUse(String customerCode) {
310	        for (Owner existing : this.clinicService.findAllOwners()) {
311	            if (customerCode.equals(existing.getCustomerCode())) {
312	                return true;
313	            }
314	        }
315	        return false;
316	    }
317	
318	    /**
319	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
320	     * upper-case hex string.
321	     *
322	     * @param value the string to hash
323	     * @return the full SHA-256 digest as upper-case hex
324	     */
325	    private static String sha256UpperHex(String value) {
326	        try {
327	            byte[] digest = MessageDigest.getInstance("SHA-256")
328	                .digest(value.getBytes(StandardCharsets.UTF_8));
329	            StringBuilder sb = new StringBuilder(digest.length * 2);
330	            for (byte b : digest) {
331	                sb.append(String.format("%02X", b));
332	            }
333	            return sb.toString();
334	        } catch (NoSuchAlgorithmException ex) {
335	            throw new IllegalStateException("SHA-256 not available", ex);
336	        }
337	    }
338	
339	    /**
340	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
341	     * owner's city already contains this many owners.
342	     */
343	    private static final int CITY_CAPACITY = 50;
344	
345	    /**
346	     * The maximum number of owners that may be created on a single day. A create is rejected with
347	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
348	     * {@code registrationDate}.
349	     */
350	    private static final int DAILY_CREATE_LIMIT = 100;
351	
352	    /**
353	     * The number of owners that must already have been created for the current day before a new
354	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
355	     * owners already carry today's {@code registrationDate}.
356	     */
357	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
358	
359	    /**
360	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
361	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
362	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
363	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
364	     * falls on a business day.
365	     *
366	     * @param date the effective registration date
367	     * @return the same date when it is a weekday, otherwise the following Monday
368	     */
369	    private static LocalDate rollToBusinessDay(LocalDate date) {
370	        return switch (date.getDayOfWeek()) {
371	            case SATURDAY -> date.plusDays(2);
372	            case SUNDAY -> date.plusDays(1);
373	            default -> date;
374	        };
375	    }
376	
377	    /**
378	     * Counts the existing owners whose {@code registrationDate} equals the given (already
379	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
380	     * business day. Called before a new owner is saved, so the returned value reflects the number of
381	     * owners created for that day prior to this create.
382	     *
383	     * @param date the adjusted business-day registration date to count against
384	     * @return the number of existing owners registered on that date
385	     */
386	    private int countOwnersRegisteredOn(LocalDate date) {
387	        return (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> date.equals(existing.getRegistrationDate()))
389	            .count();
390	    }
391	
392	    /**
393	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
394	     *
395	     * @param city the city to count owners for
396	     * @return the number of existing owners in that city
397	     */
398	    private int countOwnersInCity(String city) {
399	        return (int) this.clinicService.findAllOwners().stream()
400	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
401	            .count();
402	    }
403	
404	    /**
405	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
406	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
407	     *
408	     * @param customerCode     the owner's assigned customer code
409	     * @param registrationDate the owner's registration date
410	     * @return the assigned membership number
411	     */
412	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
413	        String yy = String.format("%02d", registrationDate.getYear() % 100);
414	        return String.format("%s-M%s", customerCode, yy);
415	    }
416	
417	    /**
418	     * Counts the existing owners that already share the given first name and last name, comparing
419	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
420	     * the number of namesakes that existed prior to this create.
421	     *
422	     * @param firstName the new owner's first name
423	     * @param lastName  the new owner's last name
424	     * @return the number of existing owners with the same first and last name
425	     */
426	    private int countNamesakes(String firstName, String lastName) {
427	        int count = 0;
428	        for (Owner existing : this.clinicService.findAllOwners()) {
429	            if (firstName.equalsIgnoreCase(existing.getFirstName())
430	                && lastName.equalsIgnoreCase(existing.getLastName())) {
431	                count++;
432	            }
433	        }
434	        return count;
435	    }
436	
437	    /**
438	     * Counts the existing owners that already belong to the given household (i.e. that share the
439	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
440	     * being created yields the household's total size at the moment of creation. Owners without a
441	     * household id are ignored.
442	     *
443	     * @param householdId the new owner's assigned household id
444	     * @return the number of existing owners already in that household
445	     */
446	    private int countHouseholdMembers(String householdId) {
447	        if (householdId == null) {
448	            return 0;
449	        }
450	        int count = 0;
451	        for (Owner existing : this.clinicService.findAllOwners()) {
452	            if (householdId.equals(existing.getHouseholdId())) {
453	                count++;
454	            }
455	        }
456	        return count;
457	    }
458	
459	    /**
460	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
461	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
462	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
463	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
464	     * string is what gets stored and returned.
465	     *
466	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
467	     *
468	     * <p>Once in E.164 form the national-number length is validated against the country code: a
469	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
470	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
471	     * rule are accepted on the general 8-to-15 digit length alone.
472	     *
473	     * @param telephone the raw telephone value supplied by the client
474	     * @return the normalized E.164 telephone number
475	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
476	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
477	     *                                 after the {@code '+'}, or the wrong national-number length for
478	     *                                 its country code)
479	     */
480	    private static String normalizeTelephone(String telephone) {
481	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
482	        String digits;
483	        if (cleaned.startsWith("+")) {
484	            digits = cleaned.substring(1);
485	        } else {
486	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
487	            digits = "61" + national;
488	        }
489	        if (!digits.matches("[0-9]{8,15}")) {
490	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
491	                "telephone could not be normalized to a valid E.164 number");
492	        }
493	        validateNationalNumberLength(digits);
494	        return "+" + digits;
495	    }
496	
497	    /**
498	     * Validates the national-number length of an E.164 number (its digits, without the leading
499	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
500	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
501	     * (only the general 8-to-15 digit rule applies).
502	     *
503	     * @param digits the E.164 digits without the leading {@code '+'}
504	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
505	     *                                 digits does not match the country code's required length
506	     */
507	    private static void validateNationalNumberLength(String digits) {
508	        E164PhoneNumbers.countryCode(digits)
509	            .ifPresent(code -> {
510	                int nationalLength = digits.length() - code.length();
511	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
512	                if (nationalLength != required) {
513	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
514	                        "telephone must have " + required
515	                            + " national digits for country code +" + code);
516	                }
517	            });
518	    }
519	
520	    /**
521	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
522	     * containing at least one dot, none of the three sections containing whitespace or an
523	     * additional {@code @}.
524	     */
525	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
526	
527	    /**
528	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
529	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
530	     * case-insensitively against the domain (the part after the {@code @}).
531	     */
532	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
533	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
534	
535	    /**
536	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
537	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
538	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
539	     * lower-cased.
540	     *
541	     * @param email the raw email value supplied by the client, possibly {@code null}
542	     * @return the lower-cased email, or {@code null} when none was supplied
543	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
544	     *                                 is not a syntactically valid address, or its domain is on the
545	     *                                 disposable-domain blocklist
546	     */
547	    private static String normalizeEmail(String email) {
548	        if (email == null) {
549	            return null;
550	        }
551	        if (!EMAIL_PATTERN.matcher(email).matches()) {
552	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
553	                "email must be a syntactically valid address");
554	        }
555	        String normalized = email.toLowerCase(Locale.ROOT);
556	        String domain = normalized.substring(normalized.indexOf('@') + 1);
557	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
558	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
559	                "email domain " + domain + " is not allowed");
560	        }
561	        return normalized;
562	    }
563	
564	    /**
565	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
566	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
567	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
568	     */
569	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
570	        "NSW", new int[] {2000, 2099},
571	        "VIC", new int[] {3000, 3099},
572	        "QLD", new int[] {4000, 4099});
573	
574	    /**
575	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
576	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
577	     * four-digit format is enforced by request validation; here the value is range-checked: when the
578	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
579	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
580	     * accepts any four-digit postcode.
581	     *
582	     * @param city     the owner's city
583	     * @param postcode the owner's postcode, possibly {@code null}
584	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
585	     *                                 out of range for the city's region
586	     */
587	    private static void validatePostcode(String city, String postcode) {
588	        if (postcode == null) {
589	            return;
590	        }
591	        String region = OwnerMapper.CITY_REGION.get(city);
592	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
593	        if (range == null) {
594	            return;
595	        }
596	        int value = Integer.parseInt(postcode);
597	        if (value < range[0] || value > range[1]) {
598	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
599	                "postcode " + postcode + " is not valid for region " + region);
600	        }
601	    }
602	
603	    /**
604	     * Common street-type abbreviations expanded to their full word during address normalization.
605	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
606	     */
607	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
608	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
609	
610	    /**
611	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
612	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
613	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
614	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
615	     *
616	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
617	     *
618	     * @param address the raw address supplied by the client, possibly {@code null}
619	     * @return the normalized address
620	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
621	     *                                 after normalization (required field)
622	     */
623	    private static String normalizeAddress(String address) {
624	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
625	        if (collapsed.isEmpty()) {
626	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
627	                "address must not be blank");
628	        }
629	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
630	        StringBuilder normalized = new StringBuilder();
631	        for (int i = 0; i < tokens.length; i++) {
632	            if (i > 0) {
633	                normalized.append(' ');
634	            }
635	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
636	        }
637	        return normalized.toString();
638	    }
639	
640	    /**
641	     * Determines whether the given whole identity key already belongs to any owner other than the
642	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
643	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
644	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
645	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
646	     *
647	     * @param identityKey the identity key to look for
648	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
649	     * @return {@code true} if another owner already has the same identity key
650	     */
651	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
652	        for (Owner existing : this.clinicService.findAllOwners()) {
653	            if (excludeId != null && excludeId.equals(existing.getId())) {
654	                continue;
655	            }
656	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
657	                return true;
658	            }
659	        }
660	        return false;
661	    }
662	
663	    /**
664	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
665	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
666	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
667	     * (identical identity key) has already been rejected with a 409 before this runs, so this
668	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
669	     * so the result is deterministic when several owners qualify.
670	     *
671	     * @param owner the new owner being created, with its telephone already normalized
672	     * @return the matching existing owner, or {@code null} when none qualifies
673	     */
674	    private Owner findPossibleDuplicate(Owner owner) {
675	        if (owner.getLastName() == null || owner.getPostcode() == null) {
676	            return null;
677	        }
678	        return this.clinicService.findAllOwners().stream()
679	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
680	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
681	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
682	            .min(Comparator.comparingInt(Owner::getId))
683	            .orElse(null);
684	    }
685	
686	}
